from fastapi import APIRouter
from fastapi.responses import HTMLResponse

from newsintel.api.dependencies import AnalystAuth
from newsintel.api.ui import COMMON_JS, render_app_page

router = APIRouter(tags=["historical-dashboard"])


@router.get("/historical-research", response_class=HTMLResponse)
async def historical_research_dashboard(auth: AnalystAuth) -> str:
    body = """
<section class="page-head"><div><div class="eyebrow">Historical research</div><h1>Research</h1><p class="lead">Find earlier reports, archived copies and primary documents to understand the developments that led to today’s story.</p></div></section>
<section class="panel">
  <div class="tabs" role="tablist"><button class="tab active" data-tab="search" type="button" role="tab" aria-selected="true">Search history</button><button class="tab" data-tab="archives" type="button" role="tab" aria-selected="false">Archive lookup</button></div>
  <div id="tab-search" class="tab-panel active">
    <div class="grid four"><label>Query<input id="query" maxlength="500" placeholder="Topic, person, event or exact phrase" /></label><label>From date<input id="fromDate" type="date" /></label><label>To date<input id="toDate" type="date" /></label><label>Language<input id="language" maxlength="35" placeholder="en, hi, en-IN" /></label></div>
    <div class="section-head" style="margin-top:16px"><div><h2>Search scope</h2><div class="muted small">Your internal corpus is always searched. External provider failures do not erase internal or other-provider results.</div></div><button id="searchButton" type="button">Search</button></div>
    <div class="filters" id="providerChoices"><label class="filter-chip"><input type="checkbox" value="gdelt" checked /> GDELT</label><label class="filter-chip"><input type="checkbox" value="guardian" checked /> Guardian</label><label class="filter-chip"><input type="checkbox" value="new_york_times" checked /> New York Times</label><label class="filter-chip"><input type="checkbox" value="news_api" checked /> NewsAPI</label><label class="filter-chip"><input type="checkbox" value="google_fact_check" checked /> Google Fact Check</label></div>
    <p id="searchMessage" class="muted small" aria-live="polite"></p><div id="providerStatuses" class="pill-row"></div><div id="results" class="article-list" style="margin-top:16px"></div>
  </div>
  <div id="tab-archives" class="tab-panel">
    <div class="grid two"><label>Original URL<input id="archiveUrl" type="url" placeholder="https://example.com/article" /></label><label>Nearest to<input id="archiveTimestamp" type="datetime-local" /></label></div>
    <div class="toolbar" style="margin-top:14px"><button id="archiveButton" type="button">Find snapshots</button><span id="archiveMessage" class="muted small" aria-live="polite"></span></div><div id="archiveStatuses" class="pill-row" style="margin-top:10px"></div><div id="archiveResults" class="article-list" style="margin-top:16px"></div>
  </div>
</section>
"""
    scripts = f"""<script>{COMMON_JS}
function clear(node){{while(node.firstChild)node.removeChild(node.firstChild)}}
function setMessage(id,text,kind=''){{const n=document.getElementById(id);n.textContent=text;n.className=kind?`notice ${{kind}}`:'muted small'}}
function addPill(container,text,kind='neutral'){{const p=document.createElement('span');p.className=`pill ${{kind}}`;p.textContent=text;container.appendChild(p)}}
function addResult(container,item){{const card=document.createElement('article');card.className='story-card';const main=document.createElement('div');const pills=document.createElement('div');pills.className='pill-row';const provider=document.createElement('span');provider.className='pill neutral';provider.textContent=item.provider||'source';pills.appendChild(provider);if(item.result_type){{const type=document.createElement('span');type.className='pill neutral';type.textContent=niTitle(item.result_type);pills.appendChild(type)}}main.appendChild(pills);const h=document.createElement('h2');h.textContent=item.title||'Untitled result';main.appendChild(h);const meta=document.createElement('div');meta.className='muted small';meta.textContent=`${{item.source_name||'Unknown source'}} · ${{niDate(item.published_at)}}`;main.appendChild(meta);if(item.snippet){{const s=document.createElement('p');s.className='muted';s.textContent=item.snippet;main.appendChild(s)}}card.appendChild(main);const side=document.createElement('div');side.className='story-side';if(item.internal_article_id){{const a=document.createElement('a');a.className='button secondary';a.href=`/articles/${{item.internal_article_id}}/intelligence`;a.textContent='Open intelligence';side.appendChild(a)}}else{{const url=niSafeUrl(item.url);if(url!=='#'){{const a=document.createElement('a');a.className='button secondary';a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Open source';side.appendChild(a)}}}}card.appendChild(side);container.appendChild(card)}}
async function searchHistorical(){{const button=document.getElementById('searchButton'),statuses=document.getElementById('providerStatuses'),results=document.getElementById('results');clear(statuses);clear(results);const query=document.getElementById('query').value.trim();if(query.length<2){{setMessage('searchMessage','Enter at least two characters.','warn');return}}const providers=Array.from(document.querySelectorAll('#providerChoices input:checked')).map(x=>x.value);const payload={{query,providers,limit:100}};const from=document.getElementById('fromDate').value,to=document.getElementById('toDate').value,language=document.getElementById('language').value.trim();if(from)payload.from_date=from;if(to)payload.to_date=to;if(language)payload.language=language;button.disabled=true;setMessage('searchMessage','Searching configured providers…');try{{const internalPayload={{query,limit:100}};if(from)internalPayload.from_date=from;if(to)internalPayload.to_date=to;const [internalResult,externalResult]=await Promise.allSettled([niApi('/api/v1/historical/internal/search',{{method:'POST',body:JSON.stringify(internalPayload)}}),providers.length?niApi('/api/v1/historical/search',{{method:'POST',body:JSON.stringify(payload)}}):Promise.resolve({{results:[],provider_statuses:[],duplicates_collapsed:0}})]);let total=0;if(internalResult.status==='fulfilled'){{const d=internalResult.value;addPill(statuses,`Internal corpus: ${{d.result_count}} results`,'good');for(const item of d.results||[]){{addResult(results,{{title:item.title,url:item.url,provider:'internal corpus',result_type:`article v${{item.version_number}}`,source_name:`${{item.claim_count}} claims`,published_at:item.published_at||item.retrieved_at,snippet:item.snippet,internal_article_id:item.article_id}});total++}}}}else addPill(statuses,'Internal corpus: failed','bad');if(externalResult.status==='fulfilled'){{const d=externalResult.value;for(const st of d.provider_statuses||[])addPill(statuses,`${{st.provider}}: ${{st.success?`${{st.result_count}} results`:(st.message||st.error_code||'failed')}}`,st.success?'good':'bad');for(const item of d.results||[]){{addResult(results,item);total++}}setMessage('searchMessage',`${{total}} displayed results · ${{d.duplicates_collapsed||0}} external duplicates collapsed.`)}}else{{addPill(statuses,'External providers: failed','bad');setMessage('searchMessage',`${{total}} internal results displayed; external search failed.`)}}if(!total){{const e=document.createElement('div');e.className='empty';e.textContent='No historical results matched this search.';results.appendChild(e)}}}}catch(e){{setMessage('searchMessage',`Search failed: ${{e.message}}`,'bad')}}finally{{button.disabled=false}}}}
async function lookupArchives(){{const button=document.getElementById('archiveButton'),statuses=document.getElementById('archiveStatuses'),results=document.getElementById('archiveResults');clear(statuses);clear(results);const url=document.getElementById('archiveUrl').value.trim();if(niSafeUrl(url)==='#'){{setMessage('archiveMessage','Enter a valid HTTP or HTTPS URL.','warn');return}}const payload={{url,providers:['wayback','common_crawl'],limit:20}};const ts=document.getElementById('archiveTimestamp').value;if(ts)payload.timestamp=new Date(ts).toISOString();button.disabled=true;setMessage('archiveMessage','Looking up archive indexes…');try{{const data=await niApi('/api/v1/historical/archives/lookup',{{method:'POST',body:JSON.stringify(payload)}});for(const st of data.provider_statuses||[])addPill(statuses,`${{st.provider}}: ${{st.success?`${{st.result_count}} snapshots`:(st.message||st.error_code||'failed')}}`,st.success?'good':'bad');for(const s of data.snapshots||[])addResult(results,{{title:`Archived snapshot · ${{s.provider}}`,url:s.archived_url,provider:s.provider,result_type:'archive_snapshot',source_name:s.mime_type||'Archive',published_at:s.captured_at,snippet:s.digest?`Digest: ${{s.digest}}`:null}});setMessage('archiveMessage',`${{(data.snapshots||[]).length}} snapshots found.`);if(!(data.snapshots||[]).length){{const e=document.createElement('div');e.className='empty';e.textContent='No archive snapshots were returned.';results.appendChild(e)}}}}catch(e){{setMessage('archiveMessage',`Archive lookup failed: ${{e.message}}`,'bad')}}finally{{button.disabled=false}}}}
niInitTabs();document.getElementById('searchButton').addEventListener('click',searchHistorical);document.getElementById('archiveButton').addEventListener('click',lookupArchives);document.getElementById('query').addEventListener('keydown',e=>{{if(e.key==='Enter')searchHistorical()}});
</script>"""
    return render_app_page(title="Historical Research", body=body, active="research", role=getattr(getattr(auth, "role", None), "value", "analyst"), scripts=scripts)
